WITH flattened AS (SELECT id, host, level, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, v) SELECT id, status_code, key, v, LEAD(status_code) OVER (PARTITION BY level ORDER BY status_code, id, key) AS next_status_code, LAG(status_code) OVER (PARTITION BY level ORDER BY status_code, id, key) AS prev_status_code, ROW_NUMBER() OVER (PARTITION BY level ORDER BY status_code, id, key) AS row_seq, LAST_VALUE(key, TRUE) OVER (PARTITION BY key ORDER BY status_code, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_key FROM flattened;
